// ============================================
// VALIDATION INPUT
// ============================================

const input = $input.first().json;
const body = input.body || {};
const headers = input.headers || {};

// --- Extraction Project ID ---
const projectId = headers['x-project-id'] 
  || headers['X-Project-ID'] 
  || headers['X-Project-Id']
  || 'unknown';

// --- Validation discord_user_id ---
if (!body.discord_user_id) {
  return {
    error: true,
    error_code: 'MISSING_USER_ID',
    message: 'Le champ "discord_user_id" est requis'
  };
}

// --- Validation adresse ---
if (!body.full_name) {
  return {
    error: true,
    error_code: 'MISSING_FULL_NAME',
    message: 'Le champ "full_name" est requis'
  };
}

if (!body.line1) {
  return {
    error: true,
    error_code: 'MISSING_LINE1',
    message: 'Le champ "line1" est requis'
  };
}

if (!body.city) {
  return {
    error: true,
    error_code: 'MISSING_CITY',
    message: 'Le champ "city" est requis'
  };
}

if (!body.postal_code) {
  return {
    error: true,
    error_code: 'MISSING_POSTAL_CODE',
    message: 'Le champ "postal_code" est requis'
  };
}

// --- Retour des donnees validees ---
return {
  error: false,
  data: {
    discord_user_id: body.discord_user_id,
    address: {
      label: body.label || null,
      full_name: body.full_name,
      phone: body.phone || null,
      line1: body.line1,
      line2: body.line2 || null,
      city: body.city,
      postal_code: body.postal_code,
      country_code: body.country_code || 'FR',
      is_default: body.is_default || false
    },
    project_id: projectId
  }
};

// ============================================
// FORMAT SUCCESS RESPONSE
// ============================================

const apiResponse = $input.first().json;

// --- Check API errors ---
if (apiResponse.error || apiResponse.success === false) {
  return {
    success: false,
    error: {
      code: apiResponse.error?.code || 'API_ERROR',
      message: apiResponse.error?.message || 'Erreur API',
      http_status: apiResponse.error?.http_status || 500
    }
  };
}

// --- Success response ---
const address = apiResponse.address || apiResponse;
return {
  success: true,
  message: 'Adresse ajoutee',
  address: {
    id: address.id,
    label: address.label,
    full_name: address.full_name,
    line1: address.line1,
    line2: address.line2,
    city: address.city,
    postal_code: address.postal_code,
    country_code: address.country_code,
    is_default: address.is_default
  }
};

// ============================================
// FORMAT ERROR RESPONSE (Validation)
// ============================================

const input = $input.first().json;

return {
  success: false,
  error: {
    code: input.error_code || 'VALIDATION_ERROR',
    message: input.message || 'Erreur de validation',
    http_status: 400
  }
};

